1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! Minimal static aarch64 ELF64 loader.
4	//!
5	//! Just enough to bring up the VM server (slice 3.4): parse the ELF header,
6	//! walk the program headers, and map each `PT_LOAD` segment into a freshly
7	//! built [`AddrSpace`]. No dynamic relocations, no interpreter, no symbol
8	//! resolution — the user binaries are statically linked `ET_EXEC` images
9	//! produced by `servers/*/user.ld`, which keeps every segment page-aligned
10	//! (vaddr *and* file offset) so this loader never has to split a page across
11	//! two segments.
12	//!
13	//! All field reads are explicit little-endian (`from_le_bytes`) because the
14	//! ELF bytes are embedded via `include_bytes!` and carry no alignment
15	//! guarantee. Frames come from the slice-3.1a allocator (zeroed on hand-out,
16	//! so a segment's BSS tail is satisfied for free) and are copied into via
17	//! HHDM, mirroring `userland::build_stub`'s stub-blob copy.
18	
19	use crate::arch::aarch64::addrspace::{AddrSpace, MapError, Prot};
20	use crate::arch::aarch64::mmu::{PAGE_SIZE, flush_icache_range};
21	use crate::mm::{alloc_frame, phys_to_hhdm};
22	use minixrs_kernel_shared::brand;
23	
24	/// Errors the loader can surface. All are fatal at boot (the embedded VM ELF
25	/// is produced by our own build, so any of these means a build/loader bug).
26	#[derive(Copy, Clone, Debug, PartialEq, Eq)]
27	pub enum ElfError {
28	    /// Too few bytes for the ELF header or a program header table entry.
29	    Truncated,
30	    /// `e_ident` magic is not `\x7fELF`.
31	    BadMagic,
32	    /// Not `ELFCLASS64`.
33	    BadClass,
34	    /// Not little-endian (`ELFDATA2LSB`).
35	    BadData,
36	    /// `e_machine` is not `EM_AARCH64`.
37	    BadMachine,
38	    /// `e_type` is not `ET_EXEC`.
39	    BadType,
40	    /// `e_phentsize` is not the expected 56 bytes.
41	    BadPhentsize,
42	    /// A `PT_LOAD` segment is not page-aligned (vaddr or file offset), or its
43	    /// file span exceeds its memory span.
44	    Misaligned,
45	    /// A segment requested both write and execute permission (W^X violation).
46	    WriteExec,
47	    /// The address-space mapping failed (out of memory, already mapped, …).
48	    Map(MapError),
49	    /// No PT_NOTE note with owner "minixrs\0", type NT_MINIXRS_IDENT (M1).
50	    MissingBrand,
51	    /// Brand present but built for an ABI this kernel does not speak.
52	    UnsupportedAbi(u32),
53	}
54	
55	impl From<MapError> for ElfError {
56	    fn from(e: MapError) -> Self {
57	        ElfError::Map(e)
58	    }
59	}
60	
61	// ELF identification / header field offsets and constants (Elf64).
62	const EI_CLASS: usize = 4;
63	const EI_DATA: usize = 5;
64	const ELFCLASS64: u8 = 2;
65	const ELFDATA2LSB: u8 = 1;
66	const EM_AARCH64: u16 = 0xB7;
67	const ET_EXEC: u16 = 2;
68	const EHDR_SIZE: usize = 64;
69	const PHDR_SIZE: usize = 56;
70	
71	const PT_LOAD: u32 = 1;
72	const PF_X: u32 = 1;
73	const PF_W: u32 = 2;
74	
75	fn rd_u16(b: &[u8], off: usize) -> Result<u16, ElfError> {
76	    b.get(off..off + 2)
77	        .map(|s| u16::from_le_bytes([s[0], s[1]]))
78	        .ok_or(ElfError::Truncated)
79	}
80	
81	fn rd_u32(b: &[u8], off: usize) -> Result<u32, ElfError> {
82	    b.get(off..off + 4)
83	        .map(|s| u32::from_le_bytes([s[0], s[1], s[2], s[3]]))
84	        .ok_or(ElfError::Truncated)
85	}
86	
87	fn rd_u64(b: &[u8], off: usize) -> Result<u64, ElfError> {
88	    b.get(off..off + 8)
89	        .map(|s| u64::from_le_bytes([s[0], s[1], s[2], s[3], s[4], s[5], s[6], s[7]]))
90	        .ok_or(ElfError::Truncated)
91	}
92	
93	/// Load every `PT_LOAD` segment of `elf` into `aspace` and return the entry
94	/// point virtual address (`e_entry`).
95	pub fn load_into(elf: &[u8], aspace: &mut AddrSpace) -> Result<u64, ElfError> {
96	    if elf.len() < EHDR_SIZE {
97	        return Err(ElfError::Truncated);
98	    }
99	    if elf[0..4] != [0x7f, b'E', b'L', b'F'] {
100	        return Err(ElfError::BadMagic);
101	    }
102	    if elf[EI_CLASS] != ELFCLASS64 {
103	        return Err(ElfError::BadClass);
104	    }
105	    if elf[EI_DATA] != ELFDATA2LSB {
106	        return Err(ElfError::BadData);
107	    }
108	    if rd_u16(elf, 16)? != ET_EXEC {
109	        return Err(ElfError::BadType);
110	    }
111	    if rd_u16(elf, 18)? != EM_AARCH64 {
112	        return Err(ElfError::BadMachine);
113	    }
114	
115	    let e_entry = rd_u64(elf, 24)?;
116	    let e_phoff = rd_u64(elf, 32)? as usize;
117	    let e_phentsize = rd_u16(elf, 54)? as usize;
118	    let e_phnum = rd_u16(elf, 56)? as usize;
119	    if e_phentsize != PHDR_SIZE {
120	        return Err(ElfError::BadPhentsize);
121	    }
122	
123	    // M1: refuse an image without the minixrs identity note
124	    // (tooling/docs/abi-note.md). This is the single choke point under
125	    // `load_exec_image`, covering boot, exec, and future exec-from-FS.
126	    match brand::scan_brand(elf) {
127	        Ok(_) => {}
128	        Err(brand::BrandError::UnsupportedAbi(v)) => return Err(ElfError::UnsupportedAbi(v)),
129	        Err(brand::BrandError::MissingBrand) => return Err(ElfError::MissingBrand),
130	        Err(brand::BrandError::Malformed) => return Err(ElfError::Truncated),
131	    }
132	
133	    for i in 0..e_phnum {
134	        let ph = e_phoff + i * e_phentsize;
135	        if rd_u32(elf, ph)? != PT_LOAD {
136	            continue;
137	        }
138	        let p_flags = rd_u32(elf, ph + 4)?;
139	        let p_offset = rd_u64(elf, ph + 8)? as usize;
140	        let p_vaddr = rd_u64(elf, ph + 16)?;
141	        let p_filesz = rd_u64(elf, ph + 32)? as usize;
142	        let p_memsz = rd_u64(elf, ph + 40)? as usize;
143	
144	        load_segment(elf, aspace, p_flags, p_offset, p_vaddr, p_filesz, p_memsz)?;
145	    }
146	
147	    Ok(e_entry)
148	}
149	
150	#[allow(clippy::too_many_arguments)]
151	fn load_segment(
152	    elf: &[u8],
153	    aspace: &mut AddrSpace,
154	    p_flags: u32,
155	    p_offset: usize,
156	    p_vaddr: u64,
157	    p_filesz: usize,
158	    p_memsz: usize,
159	) -> Result<(), ElfError> {
160	    // Page-aligned segments keep the per-page copy below trivial. Bit-and
161	    // alignment check mirrors `addrspace::check_va`'s idiom.
162	    let page_mask = PAGE_SIZE as u64 - 1;
163	    if p_vaddr & page_mask != 0 || (p_offset as u64) & page_mask != 0 || p_filesz > p_memsz {
164	        return Err(ElfError::Misaligned);
165	    }
166	    // The file region must actually be present in the embedded image.
167	    if p_offset
168	        .checked_add(p_filesz)
169	        .map(|e| e > elf.len())
170	        .unwrap_or(true)
171	    {
172	        return Err(ElfError::Truncated);
173	    }
174	
175	    let writable = p_flags & PF_W != 0;
176	    let executable = p_flags & PF_X != 0;
177	    if writable && executable {
178	        return Err(ElfError::WriteExec);
179	    }
180	    let prot = match (writable, executable) {
181	        (false, true) => Prot::RO_CODE,
182	        (true, false) => Prot::RW_DATA,
183	        (false, false) => Prot::RO_DATA,
184	        (true, true) => unreachable!("W^X checked above"),
185	    };
186	
187	    let n_pages = p_memsz.div_ceil(PAGE_SIZE);
188	    for page_idx in 0..n_pages {
189	        let va = p_vaddr + (page_idx * PAGE_SIZE) as u64;
190	        let frame = alloc_frame().ok_or(ElfError::Map(MapError::OutOfMemory))?;
191	
192	        // Copy this page's slice of file data; the rest of the frame stays
193	        // zero (BSS tail). `file_page_start` is the byte offset within the
194	        // segment, not the file.
195	        let file_page_start = page_idx * PAGE_SIZE;
196	        let copy_len = p_filesz.saturating_sub(file_page_start).min(PAGE_SIZE);
197	        if copy_len > 0 {
198	            let src = &elf[p_offset + file_page_start..p_offset + file_page_start + copy_len];
199	            // SAFETY: `frame` was just allocated (exclusively ours, zeroed, and
200	            // HHDM-mapped); `src` is a bounds-checked subslice of the embedded
201	            // ELF. Disjoint regions, `copy_len <= PAGE_SIZE`.
202	            unsafe {
203	                let dst = phys_to_hhdm(frame.addr());
204	                core::ptr::copy_nonoverlapping(src.as_ptr(), dst, copy_len);
205	                if executable {
206	                    flush_icache_range(dst as u64, copy_len);
207	                }
208	            }
209	        }
210	
211	        aspace.map_page(va, frame.addr(), prot)?;
212	    }
213	
214	    Ok(())
215	}
