3	//! minix.rs `worker` — the slice-4.7 exec target.
4	//!
5	//! A tiny freestanding EL0 program that is *not* a boot server: it is packed
6	//! into the boot-image archive only so `SYS_EXEC` can resolve it by name, and it
7	//! is never loaded at boot (`kernel/build.rs` tags its MXBI record with
8	//! `com::EXEC_ONLY_PROC_NR`). PM's `handle_exec` selects it; the kernel loads it
9	//! into a forked child's fresh address space, replacing the child's image.
10	//!
11	//! Since EL0 has no console, the worker proves it ran through observable IPC: a
12	//! few `PM_GETPID` round-trips (visible as `[ipc] caller=<child nr> target=0x0`,
13	//! returning the child's preserved pid) followed by `PM_EXIT(0)`, which tears it
14	//! down so the parent's `wait()` reaps it and the fork loop recycles the slot.
15	//!
16	//! Built as a freestanding aarch64 ELF (`userland/worker/user.ld`). It uses
17	//! `minix-ipc` directly — no `server-rt`/SEF, because it is a plain user
18	//! program, not a server. The `_start` shim and panic handler are gated to
19	//! `not(test)`.
20	
21	#![cfg_attr(not(test), no_std)]
22	#![cfg_attr(not(test), no_main)]
23	
24	minixrs_abi_note::brand!();
25	
26	use minixrs_ipc::ipc_sendrec;
27	use minixrs_kernel_shared::Message;
28	use minixrs_kernel_shared::callnr::{PM_EXIT, PM_GETPID};
29	use minixrs_kernel_shared::com::{PM_PROC_NR, boot_endpoint};
30	
31	/// Number of observable `PM_GETPID` round-trips before exiting — enough to make
32	/// the worker's activity unmistakable in the boot trace without flooding it.
33	const GETPID_ROUNDS: usize = 3;
34	
35	/// ELF entry point. Exec primes `SP_EL0` before `eret`, so `_start` can dive
36	/// straight into Rust without setting up a stack itself.
37	#[cfg(not(test))]
38	#[unsafe(no_mangle)]
39	#[cfg_attr(target_os = "minixrs", unsafe(link_section = ".text._start"))]
40	pub extern "C" fn _start() -> ! {
41	    main()
42	}
43	
44	#[cfg_attr(test, allow(dead_code))]
45	fn main() -> ! {
46	    let pm = boot_endpoint(PM_PROC_NR);
47	
48	    // Prove the new image is running: a few getpid round-trips. PM replies with
49	    // this proc's preserved pid (exec keeps the fork child's identity).
50	    for _ in 0..GETPID_ROUNDS {
51	        let mut msg = Message {
52	            m_source: 0,
53	            m_type: PM_GETPID,
54	            payload: [0u8; 96],
55	        };
56	        let _ = ipc_sendrec(pm, &mut msg);
57	    }
58	
59	    // exit(0): status 0 sits in the zeroed payload `0..4`. PM tears us down via
60	    // SYS_EXIT rather than replying, so this SENDREC never returns.
61	    let mut msg = Message {
62	        m_source: 0,
63	        m_type: PM_EXIT,
64	        payload: [0u8; 96],
65	    };
66	    let _ = ipc_sendrec(pm, &mut msg);
67	
68	    // Unreachable: PM never replies to a dead child.
69	    loop {
70	        core::hint::spin_loop()
71	    }
72	}
73	
74	// The freestanding panic handler; under `cargo test` std supplies its own.
75	#[cfg(not(test))]
76	#[panic_handler]
77	fn panic(_: &core::panic::PanicInfo) -> ! {
78	    loop {
79	        core::hint::spin_loop()
80	    }
81	}
