1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! minix.rs `init` — PID 1, the first user process (slice 4.8).
4	//!
5	//! Unlike the demo stubs it replaces, `init` is a real boot module: it is packed
6	//! into the boot-image archive with its true proc number (`INIT_PROC_NR = 10`)
7	//! and loaded + made runnable by the ordinary boot loop
8	//! (`kernel/src/arch/aarch64/userland.rs`), not hand-released by PM. It runs as
9	//! an ordinary user process — the shared `USER_PRIV_ID` privilege (SENDREC to PM
10	//! and VFS, and no kernel calls at all) — so the whole process lifecycle flows
11	//! through PM, and every byte of output through VFS, in the POSIX shape
12	//! (user → server, never user → kernel).
13	//!
14	//! `init` is the live exercise for the Phase-4 process machinery that the
15	//! slice-4.6/4.7 stub E demonstrated: it forks a child, the child execs the
16	//! `worker` binary (which runs a few `PM_GETPID` round-trips then exits), and
17	//! the parent `wait`s
18	//! to reap the zombie before looping to fork again. Each cycle recycles the same
19	//! fork-pool slot with an advancing endpoint generation — observable in the boot
20	//! trace as `SYS_FORK` / `SYS_EXEC` / `SYS_EXIT` triples.
21	//!
22	//! Slice 5.4 gives it a voice. Before the fork loop it writes to **fd 1 and fd
23	//! 2** through VFS, which grants the buffer on to the TTY driver — the POSIX
24	//! write path, end to end, from an ordinary user process. init has no debug
25	//! channel of its own (`SYS_DIAGCTL` is a kernel call, and a user proc holds
26	//! none), so it reports *through the path under test*: if the path regresses the
27	//! lines change or vanish, and the boot markers go with them. See [`announce`].
28	//!
29	//! Built as a freestanding aarch64 ELF (`userland/init/user.ld`). It uses
30	//! `minix-ipc` directly — no `server-rt`/SEF, because it is a plain user program,
31	//! not a server. The `_start` shim and panic handler are gated to `not(test)`.
32	
33	#![cfg_attr(not(test), no_std)]
34	#![cfg_attr(not(test), no_main)]
35	
36	minixrs_abi_note::brand!();
37	
38	use minixrs_ipc::ipc_sendrec;
39	use minixrs_kernel_shared::Message;
40	use minixrs_kernel_shared::callnr::{
41	    CDEV_MAX_IO, PM_EXEC, PM_FORK, PM_WAIT, VFS_BUF_OFF, VFS_FD_OFF, VFS_LEN_OFF, VFS_WRITE,
42	};
43	use minixrs_kernel_shared::com::{PM_PROC_NR, VFS_PROC_NR, boot_endpoint};
44	use minixrs_kernel_shared::endpoint::Endpoint;
45	use minixrs_kernel_shared::error::{EBADF, EFAULT, EINVAL, ENOSYS, OK};
46	use minixrs_kernel_shared::message::USER_VA_TOP;
47	use minixrs_kernel_shared::uspace::USER_DEVICE_WINDOW_BASE;
48	
49	/// The boot loader primes `SP_EL0` before `eret`, so `_start` can dive straight
50	/// into Rust without setting up a stack itself.
51	#[cfg(not(test))]
52	#[unsafe(no_mangle)]
53	#[cfg_attr(target_os = "minixrs", unsafe(link_section = ".text._start"))]
54	pub extern "C" fn _start() -> ! {
55	    main()
56	}
57	
58	/// Standard output, pre-opened by VFS to the console — POSIX's inheritance
59	/// convention, which is what lets init write before any filesystem exists.
60	const STDOUT: i32 = 1;
61	/// Standard error, also the console. Used for the denial summary specifically so
62	/// that line proves fd 2 resolves as well as fd 1.
63	const STDERR: i32 = 2;
64	
65	/// The milestone line: the first bytes an ordinary user process ever put on the
66	/// console under its own POSIX call.
67	const HELLO: &str = "minix.rs init: hello via VFS write\n";
68	
69	/// A line long enough that no single `CDEV_WRITE` can carry it, so VFS must loop.
70	///
71	/// Sized from [`CDEV_MAX_IO`] — the driver's staging limit — even though a user
72	/// process has no business knowing that number: reading it here is what keeps the
73	/// probe *meaningful* if the limit ever moves, instead of silently degrading into
74	/// a line that fits in one transfer. That the constant is invisible in `write()`'s
75	/// result is the property under test.
76	const LOOP_LINE_LEN: usize = CDEV_MAX_IO + 32;
77	
78	/// The line itself: a rule of dashes ending in a marker that only reaches the
79	/// console if VFS re-sent with `offset` advanced. Without the loop the console
80	/// gets the first [`CDEV_MAX_IO`] bytes and `vfs-loop-end` is never printed.
81	static LOOP_LINE: [u8; LOOP_LINE_LEN] = loop_line_pattern();
82	
83	const fn loop_line_pattern() -> [u8; LOOP_LINE_LEN] {
84	    let mut b = [b'-'; LOOP_LINE_LEN];
85	    let prefix = b"minix.rs init: vfs long write ";
86	    let mut i = 0;
87	    while i < prefix.len() {
88	        b[i] = prefix[i];
89	        i += 1;
90	    }
91	    // The tail sits at the very end, past the clamp, and ends the line.
92	    let tail = b"vfs-loop-end\n";
93	    let base = LOOP_LINE_LEN - tail.len();
94	    let mut j = 0;
95	    while j < tail.len() {
96	        b[base + j] = tail[j];
97	        j += 1;
98	    }
99	    b
100	}
101	
102	const _: () = assert!(LOOP_LINE_LEN > CDEV_MAX_IO);
103	
104	/// A virtual address that is **not** mapped in init's address space, for the
105	/// `EFAULT` probe.
106	///
107	/// init's image is linked at `0x0010_0000` (`user.ld`) and the kernel maps it a
108	/// single stack page at `0x0020_0000`, so `0x0030_0000` is a hole. It costs init
109	/// no page fault: the kernel's copy engine *walks* the page tables and answers
110	/// `EFAULT` (D5) rather than dereferencing, so this probe cannot SIGSEGV the
111	/// process making it.
112	///
113	/// The probe only proves what it claims if the address is well-formed enough to
114	/// reach the page-table walk — an address VFS's own `user_range_ok` pre-check
115	/// rejected would answer `EFAULT` one hop earlier and silently test the wrong
116	/// thing. The guards below pin exactly that: non-NULL and below `USER_VA_TOP`, so
117	/// every range check on the way down passes, and clear of the kernel's device
118	/// window, which *is* mapped in some address spaces. The two layout facts it also
119	/// depends on — the link base and the stack VA — stay prose, because neither is a
120	/// shared constant a user program can see.
121	const UNMAPPED_VA: u64 = 0x0030_0000;
122	
123	const _: () = assert!(UNMAPPED_VA != 0);
124	const _: () = assert!(UNMAPPED_VA < USER_VA_TOP);
125	const _: () = assert!(UNMAPPED_VA < USER_DEVICE_WINDOW_BASE);
126	
127	/// Build a request message to PM: no payload, `m_source` is stamped by the kernel.
128	#[cfg_attr(test, allow(dead_code))]
129	fn pm_msg(m_type: i32) -> Message {
130	    Message {
131	        m_source: 0,
132	        m_type,
133	        payload: [0u8; 96],
134	    }
135	}
136	
137	#[cfg_attr(test, allow(dead_code))]
138	fn main() -> ! {
139	    let pm = boot_endpoint(PM_PROC_NR);
140	    // By boot endpoint, not through DS: init's privilege opens `ipc_to` to PM and
141	    // VFS alone, so it could not ask DS even if it wanted to. That is the point of
142	    // the user grade — a user process talks to servers, not to the registry.
143	    let vfs = boot_endpoint(VFS_PROC_NR);
144	
145	    announce(vfs);
146	
147	    loop {
148	        // fork(): PM replies to both halves of this SENDREC — the child sees
149	        // `m_type == 0`, the parent sees the child pid (`> 0`); a negative value
150	        // is an errno (e.g. `EAGAIN` when the fork table is full).
151	        let mut m = pm_msg(PM_FORK);
152	        let _ = ipc_sendrec(pm, &mut m);
153	
154	        match m.m_type {
155	            0 => {
156	                // Child: replace this image with the `worker` binary. PM issues
157	                // `SYS_EXEC` and the kernel resumes us at worker's `_start`, so
158	                // this SENDREC never returns on success.
159	                let mut e = pm_msg(PM_EXEC);
160	                let _ = ipc_sendrec(pm, &mut e);
161	                // Unreachable on success; park defensively if exec ever failed.
162	                loop {
163	                    core::hint::spin_loop()
164	                }
165	            }
166	            n if n > 0 => {
167	                // Parent: reap the child (blocks until it exits), then loop to
168	                // fork the next one.
169	                let mut w = pm_msg(PM_WAIT);
170	                let _ = ipc_sendrec(pm, &mut w);
171	            }
172	            _ => {
173	                // Transient fork failure (table full): back off briefly, retry.
174	                for _ in 0..1024 {
175	                    core::hint::spin_loop()
176	                }
177	            }
178	        }
179	    }
180	}
181	
182	/// Exercise the slice-5.4 write path, and report the result over it.
183	///
184	/// Three things go to the console, in order:
185	///
186	/// 1. **The banner** ([`HELLO`], fd 1) — the milestone. A user process, holding no
187	///    kernel calls and no grant table of its own, put bytes on the console by
188	///    calling `write`.
189	/// 2. **A line longer than one `CDEV_WRITE`** ([`LOOP_LINE`], fd 1), and the
190	///    *count* it returned. Two independent halves of the same contract: the tail
191	///    marker appears only if VFS re-sent with `offset` advanced, and `match=1`
192	///    says VFS reported the whole buffer rather than the driver's clamp. Neither
193	///    subsumes the other — a `write()` that moved every byte but returned `OK`
194	///    would print the tail and still be broken, which is exactly the bug a caller
195	///    looping on a short write would then hit forever.
196	/// 3. **Three denial probes and a summary** (fd 2, so that descriptor is proven
197	///    too). Each probe is well-formed in every respect but one — the slice-5.1
198	///    lesson that a check no marker exercises is a check that can regress
199	///    silently.
200	///
201	/// `match=1` rather than the length itself, the slice-5.3 convention: it is
202	/// self-checking, needs no formatting machinery (init has none), and does not have
203	/// to be re-derived when the line's length changes.
204	///
205	/// Best-effort: init's job is to keep the system running, so a failure here is
206	/// reported and stepped over, never fatal.
