222	/// The `VFS_WRITE` requests that must be refused, each valid but for one field.
223	///
224	///   - `bad-fd` — a perfectly good buffer written to descriptor 3, which is in
225	///     range of the fd row but not open. `EBADF`, from VFS's fd table; make the
226	///     table accept any descriptor and this write *succeeds*.
227	///   - `no-such` — a request number one past `VFS_WRITE`. `ENOSYS`, from VFS's
228	///     dispatch — and the reply itself is the assertion: a server that dropped an
229	///     unknown request instead of replying would leave init blocked here forever,
230	///     taking the whole boot with it.
231	///   - `bad-buf` — an unmapped buffer ([`UNMAPPED_VA`]). `EFAULT`, from the
232	///     kernel's page-table walk in the middle of TTY's safecopy, relayed back out
233	///     through the driver and VFS unchanged. It proves the errno survives two
234	///     hops without being flattened into a generic failure.
235	///   - `bad-len` — a negative byte count. `EINVAL`, and the check matters more
236	///     than it looks: left unchecked the length widens into a ~16 EiB `u64` on the
237	///     grant VFS is about to issue over the caller's buffer.
238	///
239	/// The one arm with no probe here is a **zero**-length write, which is a legal
240	/// no-op rather than a denial and would need a distinct positive marker to say
241	/// anything. `write::validate` covers it — and the fact that it is checked before
242	/// the buffer, so a zero-length write never issues a grant — in host tests.
243	#[cfg_attr(test, allow(dead_code))]
244	fn deny_probes(vfs: Endpoint) {
245	    let addr = HELLO.as_ptr() as usize as u64;
246	    let len = HELLO.len() as i32;
247	
248	    // (name, request, fd, buffer, length, expected reply)
249	    let probes: [(&str, i32, i32, u64, i32, i32); 4] = [
250	        ("bad-fd", VFS_WRITE, 3, addr, len, EBADF),
251	        ("no-such", VFS_WRITE + 1, STDOUT, addr, len, ENOSYS),
252	        ("bad-buf", VFS_WRITE, STDOUT, UNMAPPED_VA, len, EFAULT),
253	        ("bad-len", VFS_WRITE, STDOUT, addr, -1, EINVAL),
254	    ];
255	
256	    for (name, m_type, fd, buf, len, want) in probes {
257	        if vfs_request(vfs, m_type, fd, buf, len) != want {
258	            return report_fail(vfs, name);
259	        }
260	    }
261	    let _ = vfs_write(vfs, STDERR, "minix.rs init: vfs.deny ok n=4\n".as_bytes());
262	}
263	
264	/// Report the first failing probe by name, on fd 2.
265	///
266	/// Hand-assembled into a stack buffer: init has no formatting runtime (no
267	/// `server-rt`, so no `diag_fmt`), and the buffer's address is what VFS grants on
268	/// to the driver — legal because init stays blocked in the SENDREC for the whole
269	/// copy, so the frame outlives every use of it.
270	#[cfg_attr(test, allow(dead_code))]
271	fn report_fail(vfs: Endpoint, name: &str) {
272	    const PREFIX: &str = "minix.rs init: vfs.deny FAIL ";
273	    let mut line = [0u8; 64];
274	    let mut n = 0;
275	    for src in [PREFIX.as_bytes(), name.as_bytes(), b"\n"] {
276	        for b in src {
277	            if n < line.len() {
278	                line[n] = *b;
279	                n += 1;
280	            }
281	        }
282	    }
283	    let _ = vfs_write(vfs, STDERR, &line[..n]);
284	}
