308	/// reuse the exact same wire format and vary only the number.
309	#[cfg_attr(test, allow(dead_code))]
310	fn vfs_request(vfs: Endpoint, m_type: i32, fd: i32, buf: u64, len: i32) -> i32 {
311	    let mut m = Message {
312	        m_source: 0,
313	        m_type,
314	        payload: [0u8; 96],
315	    };
316	    m.payload[VFS_FD_OFF..VFS_FD_OFF + 4].copy_from_slice(&fd.to_ne_bytes());
317	    m.payload[VFS_LEN_OFF..VFS_LEN_OFF + 4].copy_from_slice(&len.to_ne_bytes());
318	    m.payload[VFS_BUF_OFF..VFS_BUF_OFF + 8].copy_from_slice(&buf.to_ne_bytes());
319	
320	    let trap_rc = ipc_sendrec(vfs, &mut m);
321	    if trap_rc != OK {
322	        return trap_rc;
323	    }
324	    m.m_type
325	}
