397	/// Load one boot server's ELF (`elf`) into a fresh address space, prime its
398	/// entry/stack registers, clear the boot `RTS_NO_PRIV` block, and enqueue it.
399	/// Generalizes the slice-3.4 `vm_bootstrap` over the MXBI archive (slice 4.2).
400	///
401	/// Unlike the hand-coded stubs (which use ad-hoc proc/priv slots), a boot server
402	/// occupies its *real* boot slot `nr`: `proc::init` → `init_boot_image` already
403	/// populated its name, priority, endpoint, and privilege slot (`trap_mask =
404	/// SRV_T` → RECEIVE ANY + SEND to any active slot; full `k_call_mask`). So this
405	/// fills in only the address space + EL0 entry state. No `install_*_priv` helper
406	/// is needed.
407	///
408	/// A freshly built user address space ready to become a proc's image: its
409	/// page-table root PA, ASID, program entry VA, and initial stack pointer.
410	/// Produced by [`load_exec_image`]; consumed by boot-server load and
411	/// `system::do_exec`.
412	pub(crate) struct ExecImage {
413	    pub ttbr0_pa: u64,
414	    pub asid: u8,
415	    pub entry: u64,
416	    pub sp_top: u64,
417	}
