419	/// Build a fresh address space from an ELF image: allocate the L0 root, load
420	/// the `PT_LOAD` segments (BSS satisfied for free — `alloc_frame` zeroes), map
421	/// one zeroed RW stack page at [`SERVER_STACK_VA`], and allocate an ASID. The
422	/// `AddrSpace` is `mem::forget`-ed — the page-table tree is now owned via the
423	/// returned `ttbr0_pa` (tear it down with the `do_exit` teardown sequence, never
424	/// `AddrSpace::destroy`). Returns `None` on OOM or a malformed ELF, freeing any
425	/// partial tree first so nothing leaks (the do_fork `copy_addrspace` contract).
426	///
427	/// The stack VA is shared with every boot server because each image gets its own
428	/// TTBR0, so the same low VA resolves to a distinct frame per proc.
429	///
430	/// SAFETY: single-threaded EL1; the sole caller of the frame allocator + ASID
431	/// pool for its duration. Must run after `mm::init_from_limine_memmap`.
432	pub(crate) unsafe fn load_exec_image(elf: &[u8]) -> Option<ExecImage> {
433	    let mut aspace = AddrSpace::new().ok()?;
434	
435	    let entry = match crate::boot_image::elf::load_into(elf, &mut aspace) {
436	        Ok(e) => e,
437	        Err(e) => {
438	            // A brand rejection (M1, `elf::load_into`'s scan) is surfaced
439	            // before the load unwinds — the boot path panics right after
440	            // (`load_boot_server`'s "server image load failed"), and the exec
441	            // path folds every failure into `ENOMEM`. `[brand]` is uncounted —
442	            // a stable marker, like `[efault]`. Other ElfErrors stay silent
443	            // as before.
444	            {
445	                use crate::arch::aarch64::uart::Pl011;
446	                use crate::boot_image::elf::ElfError;
447	                use core::fmt::Write;
448	                match e {
449	                    ElfError::MissingBrand => {
450	                        let _ = writeln!(Pl011::new(), "[brand] reject: missing");
451	                    }
452	                    ElfError::UnsupportedAbi(v) => {
453	                        let _ = writeln!(Pl011::new(), "[brand] reject: abi={v}");
454	                    }
455	                    _ => {}
456	                }
457	            }
458	            destroy_addrspace_with_leaves(aspace);
459	            return None;
460	        }
461	    };
462	
463	    // Stack: one zeroed RW page; SP starts at its top.
464	    let stack_frame = match alloc_frame() {
465	        Some(f) => f,
466	        None => {
467	            destroy_addrspace_with_leaves(aspace);
468	            return None;
469	        }
470	    };
471	    if aspace
472	        .map_page(SERVER_STACK_VA, stack_frame.addr(), Prot::RW_DATA)
473	        .is_err()
474	    {
475	        // `map_page` failed before linking the leaf, so free the orphan stack
476	        // frame explicitly; the leaf sweep below won't see it.
477	        free_frame(stack_frame);
478	        destroy_addrspace_with_leaves(aspace);
479	        return None;
480	    }
481	
482	    let ttbr0_pa = aspace.ttbr0_pa;
483	    // SAFETY: single-threaded EL1 context; sole accessor of the ASID pool.
484	    let asid = unsafe { alloc_asid() };
485	    // The page-table tree is durable via `ttbr0_pa`; don't run `destroy`.
486	    // `forget` (not drop) defends against a future `AddrSpace: Drop` freeing
487	    // the tree that stays live via `ttbr0_pa`.
488	    #[allow(clippy::forget_non_drop)]
489	    core::mem::forget(aspace);
490	    Some(ExecImage {
491	        ttbr0_pa,
492	        asid,
493	        entry,
494	        sp_top: SERVER_STACK_VA + PAGE_SIZE as u64,
495	    })
496	}
