498	/// Free every mapped leaf frame of a partially-built address space, then the
499	/// tree itself. Used only on the [`load_exec_image`] error paths, before any
500	/// ASID is allocated — so unlike `do_exit::teardown_addrspace` there is nothing
501	/// to flush or recycle.
502	///
503	/// The `prot.device` guard is unreachable today — the only device mapping in the
504	/// system is installed by [`load_boot_server`] *after* `load_exec_image` has
505	/// already returned successfully, so no error path here can see one. It is here
506	/// anyway because this is the leaf sweep that gets forgotten, and forgetting it
507	/// is a kernel panic (`free_frame` rejects a non-RAM PA), not a leak.
508	fn destroy_addrspace_with_leaves(aspace: AddrSpace) {
509	    let ttbr0_pa = aspace.ttbr0_pa;
510	    let _ = walk_leaves(ttbr0_pa, &mut |_va, pa, prot| {
511	        if !prot.device {
512	            free_frame(Frame::from_addr(pa));
513	        }
514	        Ok(())
515	    });
516	    aspace.destroy();
517	}
